WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) li AS key, attr_value) SELECT s.id, s.customer_id, s.created_at, s.coupon_codes, s.key, s.attr_value, CASE WHEN key RLIKE '^(gift|device)$' THEN 'GROUP_B' WHEN key RLIKE '^(utm_source|weight_kg)$' THEN 'CORE' ELSE 'EXTENDED' END AS key_zone, (SELECT SUM(x.shipping_fee) FROM orders x WHERE x.customer_id = s.customer_id) AS sum_order_shipping_fee FROM flattened s ORDER BY id NULLS LAST
